<script lang="ts">
import { createVNode, defineComponent, h, ref, withDirectives } from 'vue'
import { ElInput } from '@element-plus/components/input'
import { ElSelectV2 } from '@element-plus/components/select-v2'
import { useNamespace } from '@element-plus/hooks'
import { inputSelectEmits, inputSelectProps } from './input-select'

import type { Slot } from 'vue'
import type { InputInstance } from '@element-plus/components/input'
import type { SelectV2Instance } from '@element-plus/components/select-v2'
import type { InputSelectControl, InputSelectValue } from './input-select'

type ControlSide = 'left' | 'right'
type ControlInstance = InputInstance | SelectV2Instance

export default defineComponent({
  name: 'ElInputSelect',
  inheritAttrs: false,
  props: inputSelectProps,
  emits: inputSelectEmits,
  setup(props, { attrs, slots, emit, expose }) {
    const ns = useNamespace('input-select')
    const leftRef = ref<ControlInstance>()
    const rightRef = ref<ControlInstance>()

    const getControlSlots = (side: ControlSide) => {
      const prefix = `${side}-`

      return Object.entries(slots).reduce<Record<string, Slot>>(
        (controlSlots, [name, slot]) => {
          if (name.startsWith(prefix) && slot) {
            controlSlots[name.slice(prefix.length)] = slot
          }
          return controlSlots
        },
        {}
      )
    }

    const updateValue = (side: ControlSide, value: InputSelectValue) => {
      if (side === 'left') emit('update:leftValue', value)
      else emit('update:rightValue', value)
    }

    const handleChange = (side: ControlSide, value: InputSelectValue) => {
      if (side === 'left') emit('left-change', value)
      else emit('right-change', value)
    }

    const handleFocus = (side: ControlSide, event: FocusEvent) => {
      if (side === 'left') emit('left-focus', event)
      else emit('right-focus', event)
    }

    const handleBlur = (side: ControlSide, event: FocusEvent) => {
      if (side === 'left') emit('left-blur', event)
      else emit('right-blur', event)
    }

    const handleClear = (side: ControlSide) => {
      if (side === 'left') emit('left-clear')
      else emit('right-clear')
    }

    const handleVisibleChange = (side: ControlSide, visible: boolean) => {
      if (side === 'left') emit('left-visible-change', visible)
      else emit('right-visible-change', visible)
    }

    const renderControl = (side: ControlSide, control: InputSelectControl) => {
      const isLeft = side === 'left'
      const controlProps = (isLeft ? props.leftProps : props.rightProps) as
        | Record<string, unknown>
        | undefined
      const modelValue = isLeft ? props.leftValue : props.rightValue
      const component = control === 'input' ? ElInput : ElSelectV2
      const controlRef = isLeft ? leftRef : rightRef
      const listeners =
        control === 'select'
          ? {
              onVisibleChange: (visible: boolean) =>
                handleVisibleChange(side, visible),
            }
          : {}

      const controlVNode = withDirectives(
        createVNode(
          component,
          {
            ...(control === 'select' ? { options: [] } : {}),
            ...controlProps,
            ...listeners,
            key: `${side}-${control}`,
            ref: controlRef,
            class: [
              control === 'input' && ns.e('control'),
              ns.is(side),
              controlProps?.class as string | undefined,
            ],
            modelValue,
            'onUpdate:modelValue': (value: InputSelectValue) =>
              updateValue(side, value),
            onChange: (value: InputSelectValue) => handleChange(side, value),
            onFocus: (event: FocusEvent) => handleFocus(side, event),
            onBlur: (event: FocusEvent) => handleBlur(side, event),
            onClear: () => handleClear(side),
          },
          getControlSlots(side)
        ),
        isLeft ? props.leftDirectives : props.rightDirectives
      )

      return control === 'select'
        ? h(
            'div',
            {
              key: `${side}-${control}`,
              class: [ns.e('control'), ns.is(side)],
            },
            [controlVNode]
          )
        : controlVNode
    }

    const focus = (side: ControlSide = 'left') => {
      const controlRef = side === 'left' ? leftRef : rightRef
      controlRef.value?.focus?.()
    }

    const blur = (side: ControlSide = 'left') => {
      const controlRef = side === 'left' ? leftRef : rightRef
      controlRef.value?.blur?.()
    }

    expose({
      leftRef,
      rightRef,
      focus,
      blur,
    })

    return () =>
      h(
        'div',
        {
          ...attrs,
          class: [
            ns.b(),
            ns.is(
              'expanded',
              Boolean(props.leftProps?.expand || props.rightProps?.expand)
            ),
            attrs.class,
          ],
          'data-layout': props.layout.join('-'),
        },
        [
          renderControl('left', props.layout[0]),
          renderControl('right', props.layout[1]),
        ]
      )
  },
})
</script>
